{
  "sql": "SELECT t1.product_category_name_english, AVG(t2.review_score) AS avg_review_score, CAST(SUM(CASE WHEN t2.review_score < (SELECT AVG(review_score) FROM order_reviews WHERE order_id IN (SELECT order_id FROM vw_pedidos_validos)) THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(t2.review_score) AS pct_mala_calif, CAST(SUM(CASE WHEN t2.review_score < (SELECT AVG(review_score) FROM order_reviews WHERE order_id IN (SELECT order_id FROM vw_pedidos_validos)) AND julianday(t1.order_delivered_customer_date) - julianday(t1.order_estimated_delivery_date) > 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(t2.review_score) AS pct_mala_calif_con_retraso FROM product_category_translation t1 JOIN order_reviews t2 ON t1.product_category_name = t2.product_category_name JOIN vw_pedidos_validos t3 ON t2.order_id = t3.order_id WHERE t2.review_score < (SELECT AVG(review_score) FROM order_reviews WHERE order_id IN (SELECT order_id FROM vw_pedidos_validos)) GROUP BY t1.product_category_name_english HAVING COUNT(t2.review_score) >= 100 AND pct_mala_calif_con_retraso < (SELECT CAST(SUM(CASE WHEN julianday(order_delivered_customer_date) - julianday(order_estimated_delivery_date) > 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(order_id) FROM vw_pedidos_validos WHERE order_status = 'delivered')"
}
